custom_css:
/* 夜曲 v1.04 2025-11-19
   主题作者：咩野(DC@lambkinling)
   请勿二传二改，倒卖&商用引流司马 */

/* 使用说明: 点击气泡时才会出现小铅笔，用户小铅笔在气泡开头，角色小铅笔在气泡底部 */

/* 自定义文案: 已在代码中使用📍标记，内容自行修改。字体颜色调整css开头自定义变量中的两个“点缀色”。
   对话文本: 默认白色，调节调色盘里的对话文本改的是外发光颜色，不需要这个效果的就把q那一串代码删掉
*/

/* 英文字体 */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-720%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2F720%2Fmain.woff2%22)%20format(%22woff2%22)%2Curl(%22https%3A%2F%2Ffontsapi-storage.zeoseven.com%2F720%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");

/* ===== 0. 变量定义 ===== */
:root {
    --圆角: 5px;
    --圆角-中: 10px;
    --毛玻璃效果: 5px;
    --点缀色: rgba(220, 20, 60, 0.85);
    --点缀色-2: rgba(230, 30, 60, 0.6);
}

/* ===== 1. 文本样式 ===== */
/* 对话 */
q {
  color: rgba(255, 255, 255, 0.8) !important;
  text-shadow: 
    0 0 2px var(--SmartThemeQuoteColor),
    0 0 1px var(--SmartThemeQuoteColor),
    0 0 6px var(--SmartThemeQuoteColor);
}

/* 斜体 */
em {
  text-decoration: 0.1em underline dashed currentColor;
  text-underline-offset: 3.5px;
}

/* 删除 */
del {
    color: var(--SmartThemeUnderlineColor);
    text-decoration-color: crimson;
}

/* 代码块 */
code {
  border: none;
  box-shadow:
    1px 1px 3px #1a1a1a,
    0 0 4px #4a4a4a !important;
}

.mes pre code {
  background: var(--SmartThemeBlurTintColor);
  border-radius: 3px;
  border: none;
  outline: 1px solid #666;
  outline-offset: -4px;
  box-shadow:
    1px 1px 3px #1a1a1a,
    0 0 4px #4a4a4a !important;
}

/* md引用文本 */
blockquote {
  border-left: none !important;
  background: linear-gradient(to right, transparent, var(--SmartThemeUnderlineColor),  transparent) !important;
  color: #444 !important;
}

/* ----- 代码块内文字(没抓取完整) ----- */
.hljs {
  color: var(--SmartThemeBodyColor) !important;
  font-size: var(--mainFontSize) !important;
  line-height: 1.6;
}

/* md标题 */
.hljs-section {
  color: var(--SmartThemeEmColor) !important;
}

/* md粗体 */
.hljs-strong {
  color: var(--SmartThemeQuoteColor) !important;
}

/* ===== 2. 滚动条 & 滑动条 ===== */
/* ----- 滚动条 ----- */
::-webkit-scrollbar {
  display: none;
}

/* Firefox */
html {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--SmartThemeBorderColor) 50%, transparent) #f1f1f1;
}

/* ----- 滑动条 ----- */
input[type="range"] {
    background: var(--SmartThemeBorderColor) !important;
    border-radius: var(--圆角) !important;
    height: 2px !important;
    filter: none !important;
    box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
  filter: none !important;
  background: #292929;
  border-radius: 50%;
  border: none;
  box-shadow: 
    1px 1px 1px rgba(0, 0, 0, 0.6),
    -1px -1px 1px rgba(197, 197, 197, 0.1);
}

/* ===== 3. 聊天区域 ===== */
/* ----- 欢迎页 ----- */
.welcomePanel .recentChatList .recentChat {
    margin-bottom: 10px;
    border-radius: var(--圆角);
    background-color: var(--SmartThemeBotMesBlurTintColor);
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
   -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
    outline: 1.5px solid var(--SmartThemeBlurTintColor) !important;
    box-shadow: 0 0 3.5px var(--SmartThemeBorderColor);
}

/* 为编辑按钮区域留出空间 */
.chatNameContainer {
    padding: 1px 3.5px;
}

/* 欢迎页按钮 */
.mes_button.showRecentChats .fa-circle-chevron-down::before {
  content: "\f004";
  color: red;
}

.mes_button.hideRecentChats .fa-circle-xmark::before {
  content: "\f7a9";
  color: red;
}

#chat {
    border: none;
    background: transparent;
    scrollbar-width: none;
    /* 不要背景图模糊的话删除这行 */
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
   -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* ----- 消息框 ----- */
body .mes {
    position: relative;
    flex-direction: column;
    align-items: center;
    width: 100%; /* 宽度 */
    margin: 0 auto; /* 第一位数为上下外边距 */
    padding: 35px 10px 35px; /* 最外部气泡内边距 */
    border-radius: 0;
    border: 1px solid var(--SmartThemeBorderColor);
    border-left: none;
    border-right: none;
    background-color: var(--SmartThemeChatTintColor); /* 对应聊天背景色 */
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
   -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 最后一条消息 */
.last_mes {
  margin-bottom: 70px !important;
  border-bottom: none;
  -webkit-mask-image: linear-gradient(to top, transparent 0px, rgba(0, 0, 0, 0.4) 15px, black 40px);
  mask-image: linear-gradient(to top, transparent 0px, rgba(0, 0, 0, 0.4) 15px, black 40px);
}

.last_mes .mes_block {
  margin-bottom: 30px !important;
}

/* 消息块 */
.mes_block {
    display: flex;
    flex-direction: column;
    transform: none !important;
    padding: 8px 9px 0; /* 文本框内边距 */
    background: var(--SmartThemeBotMesBlurTintColor);
    border-radius: 15px;
    border: 0.8px solid var(--SmartThemeBorderColor);
}

.mes[is_user="true"] .mes_block {
    padding-bottom: 15px;
    background: var(--SmartThemeUserMesBlurTintColor);
}

/* 文字内容 */
.mes_text {
    padding: 0;
    text-align: justify; /* 两端对齐改成justify */
}

.mes[is_user="true"] .mes_text {
    padding-top: 5px;
}

.mes[is_user="true"] p:last-child {
    margin-bottom: 0;
}

/* --- 小铅笔 --- */
.mes_button,
.mes_edit_buttons {
  font-size: calc(var(--mainFontSize) * 1.01);
  filter: none !important;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.mes_button.hideRecentChats,
.mes_button.showRecentChats {
  opacity: 0.15;
  visibility: visible;
}

.mes_block:hover .mes_button,
.mes_block:hover .mes_edit_buttons {
  opacity: 1;
  visibility: visible;
}

/* 子按钮 */
.mes .menu_button {
    opacity: 1; 
    border-radius: var(--圆角-中);
}

/* --- 左右箭头 --- */
.swipe_right,
.swipe_left {
    border-radius: 50%;
    border: 1px solid var(--SmartThemeBorderColor);
}

.swipe_right::before,
.swipe_left::before {
    content: "\f0da";
    opacity: 0.5;
    color: var(--SmartThemeBorderColor);
}

.swipe_left::before {
    content: "\f0d9";
 }

.swipeRightBlock {
  margin-right: 10px;
}

/* ----- 思维链 ----- */
.mes_reasoning_header {
    background-color: transparent;
    margin: auto;
    padding: 0;
}

.mes_reasoning_arrow {
  display: none;
}

/* 📍思维链文字自定义 */
.mes_reasoning_header_title {
    font-size: 0;
    &::before {
        content: "𓋫 𓏴𓏴 𓏵‧₊  ₊‧𓏵 𓏴𓏴 𓋫";
        font-size: calc(var(--mainFontSize) * 0.85);
        color: var(--SmartThemeBodyColor);
        font-family: "ZSFT-720";
        font-weight: normal;
    }
}

/* 内容宽度 */
.mes_reasoning_details {
  position: relative;
  width: auto;
  max-width: 100%;
}

/* 打开状态时100%宽度 */
.mes_reasoning_details[open] {
  width: 100%;
}

.mes_reasoning_actions {
  position: absolute;
  right: 5px;
  top: 5px;
  z-index: 10;
  flex-shrink: 0;
  padding: 0 5px;
}

@media (max-width: 768px) {
  .mes_reasoning {
      width: 100%;
      max-height: 450px; /* 思维链内容高度 */
      overflow: hidden auto;
      font-size: calc(var(--mainFontSize) * 0.9);
      border: none;
      border-bottom: 1px dashed var(--SmartThemeBorderColor);
      background: var(--SmartThemeChatTintColor);
  }
   .mes_reasoning_actions {
    right: 0;
    top: -5px;
  }
}

/* ----- 名字区域 ----- */
/* Char名字置底 */
.mes[is_user="false"] .ch_name {
    order: 1;
    margin-top: 10px;
    margin-bottom: 10px;
    text-align: center;
}

/* 📍User - 消息头部装饰 */
.mes .ch_name::before {
    content: "𓋫 𓏴𓏴 𓏵‧₊  ₊‧𓏵 𓏴𓏴 𓋫";
    white-space: nowrap;
    position: absolute;
    font-family: "ZSFT-720";
    font-weight: normal;
    font-size: calc(var(--mainFontSize) * 0.85);
    transform: translateX(-50%);
    left: 50%;
}

/* 📍Char - 消息底部装饰 */
.mes[is_user="false"] .ch_name::before {
    content: ".⁺✟₊⋆————꒰ঌ˖𝕾𝖚𝖓𝖗𝖎𝖘𝖊 𝕲𝖗𝖊𝖊𝖙˖໒꒱ྀི————⋆⁺✞₊⭒";
    font-size: calc(var(--mainFontSize) * 0.95);
}

.mes_block:hover .ch_name::before {
    opacity: 0;
}

/* --- 📍名字装饰 --- */
.mes .name_text {
    position: absolute;
    white-space: nowrap;
    bottom: calc(100% - 70px); /* 上下 */
    left: 5px; /* 左右 */
    font-size: calc(var(--mainFontSize) * 2.75);
    &::before, &::after {
        content: "";
        font-family: "ZSFT-720";
        font-weight: normal;
    }
}

/* Char - 名字前缀 */
.mes .name_text::before {
    content: "「";
}

/* User - 名字前缀 */
.mes[is_user="true"] .name_text::before {
    content: "「";
}

/* User - 名字后装饰英文 */
.mes .name_text::after {
    content: "Lumière";
    position: absolute;
    top: 8px; /* 上下 */
    left: 20px; /* 左右 */
    z-index: -1;
    opacity: 0.65;
    color: var(--点缀色);
    text-shadow:
        0 0 1px var(--点缀色),
        0 0 4px var(--点缀色),
        0 0 7px var(--点缀色);
    font-size: calc(var(--mainFontSize) * 3.75); /* 大小 */
}

/* Char - 名字后缀 */
.mes[is_user="false"] .name_text::after {
    content: "Nocturne";
    color: var(--点缀色-2);
    text-shadow:
        0 0 1px var(--点缀色-2),
        0 0 4px var(--点缀色-2),
        0 0 7px var(--点缀色-2);
}

/* --- 时间戳 --- */
.mes .timestamp {
    position: absolute;
    transform: translateX(-50%);
    left: 50%;
    bottom: 10px;
}

.last_mes[is_user="false"] .timestamp {
    bottom: 25px;
}

/* 模型+隐藏楼层 */
.timestamp-icon,
.mes_ghost {
   position: absolute;
   filter: 
    drop-shadow(0 0 5px var(--点缀色))
    drop-shadow(0 0 12px var(--点缀色));
 }

.timestamp-icon {
  right: 30px;
  top: 105px;
}

.mes_ghost {
  right: 15px;
  top: 107px;
}

/* ----- 头像区域 ----- */
.last_mes .mesAvatarWrapper {
    padding: 0 !important;
}

/* 头像文案 - 位置调整 */
.mesAvatarWrapper {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-end;
  justify-content: flex-end;
  position: relative;
  margin-bottom: 15px;
  width: 100%;
  &::before {
    content: "I almost wish we were butterflies and liv'd but three summer days - three such days with you I could fill with more delight than fifty common years could ever contain."; /* User 文案 */
    position: absolute;
    width: 60%;
    top: 50%; /* 上下 */
    left: 20px; /* 左右 */
    font-size: calc(var(--mainFontSize) * 0.6); /* 大小 */
  }
}

/* 📍Char - 头像文案 */
.mes[is_user="false"] .mesAvatarWrapper::before {
  content: "我甚至希望我们是蝴蝶，只能在夏天活上三天。有你陪伴的三天，也好过庸庸碌碌五十年。";
  font-size: calc(var(--mainFontSize) * 0.65);
}

.mes .avatar {
  position: relative;
  top: -10px;
  margin-left: 5px;
  flex: 0 0 auto;
  width: 80px;
  height: 80px;
  pointer-events: none;
  margin-right: 30px;
  order: 1;
  &::before {
        content: "";
        position: absolute;
        top: 50%;
        left: 50%;
        width: 83px;
        height: 83px;
        border-radius: 50%;
        box-shadow:
            0 0 8px var(--点缀色),
            0 0 6px var(--点缀色); 
        transform: translate(-50%, -50%);
        z-index: 1;
        border: 1.5px solid var(--点缀色);
        pointer-events: none;
    }
}

.mes[is_user="false"] .avatar::before {
  box-shadow:
    0 0 8px var(--点缀色-2),
    0 0 6px var(--点缀色-2); 
  border: 1.5px solid var(--点缀色-2);
}

.mes .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* --- 楼层 + 计时器 + tokens --- */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    font-size: calc(var(--mainFontSize) * 0.65);
    transform: translateY(5px);
    padding: 0 5px;
    border-left: 1.2px solid var(--点缀色);
}

.mes .tokenCounterDisplay {
  border-right: 1.2px solid var(--点缀色);
}

.mes[is_user="false"] .mesIDDisplay,
.mes[is_user="false"] .mes_timer,
.mes[is_user="false"] .tokenCounterDisplay {
    border-color: var(--点缀色-2);
}

/* ===== 4. 菜单抽屉 ===== */
/* --- 全局头像 --- */
.avatar img,
body.big-avatar .avatar img{
    box-shadow: none;
    border: none;
}

/* --- 抽屉页背景 --- */
body .drawer-content {
    box-shadow: none;
    border-radius: 0 0 var(--圆角) var(--圆角);
    border-color: var(--SmartThemeBlurTintColor);
    border-bottom: 2px solid var(--SmartThemeBorderColor);
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
   -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 预设页 & 角色管理页 */
#left-nav-panel,
#right-nav-panel {
    border-color: var(--SmartThemeBlurTintColor);
    border-bottom: 1.5px solid var(--SmartThemeBorderColor);
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
    -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 全屏 by NAKARI */
.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize));
}

#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

@media (max-width: 600px) {
    #left-nav-panel,
    #right-nav-panel {
        max-height: calc(100dvh - var(--topBarBlockSize));
    }
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4) {
    padding: 3px 10px;
    margin-bottom: 8px;
    border-radius: 20px;
    color: #E0E0E0;
    background: linear-gradient(145deg, #232323, #383838);
    box-shadow:
        3px 3px 4px #1a1a1a,
        0 0 4px #4a4a4a;
    filter: none !important;
    border: none;
}

/* 箭头 */
.inline-drawer-icon {
    font-size: calc(var(--mainFontSize) * 1.1);
}

/* 闭合状态 */
.inline-drawer-icon::before {
    content: "⚝" !important;
}

/* 展开状态 */
.inline-drawer-icon.up::before {
    content: "☽" !important;
    font-size: calc(var(--mainFontSize) * 1.2);
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  background: linear-gradient(145deg, #292929, #383838);
  border: none;
  box-shadow:
    1px 1px 3px #1a1a1a,
    0 0 3px #4a4a4a;
}

/* 警告按钮 */
#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: crimson !important;
  color: black !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
    background: #191a1e;
    border: none;
    border-radius: 50%;
    box-shadow:
        2px 2px 2px #0e0e0e, 
        -1px -1px 2px rgba(94, 95, 94, 0.25);
    outline: 1.5px solid #191a1e;
}

.checkbox_label {
    display: flex;
    align-items: center;
}

input[type="checkbox"]:checked {
  box-shadow: 
    2px 2px 3px #0e0e0e, 
    -1px -1px 2px rgba(94, 95, 94, 0.1),
    inset 1px 1px 2px #0e0e0e,
    inset -1px -1px 1px #333;
  border: none;
}

/* by c一串 */
input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--SmartThemeBorderColor);
}

/* --- 下拉框 --- */
#character_sort_order,
select.text_pole,
select {
    outline: none !important;
    border: none !important;
    border-radius: var(--圆角);
    box-shadow:
        1px 1px 2px #1a1a1a,
        0 0 3px #4a4a4a;
}

#tag_import_setting {
    margin-top: 5px;
}

/* --- 输入框 --- */
/* 搜索框 + 部分输入框 */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select) {
    border: none;
    border-radius: var(--圆角-中);
}

input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]) {
    outline: none !important;
    border: none;
    box-shadow:
        2px 2px 4px #1a1a1a,
        0 0 4px #4a4a4a !important;
}

/* 用户设置页 - 数字输入框*/
#user-settings-block input[type="number"] {
    border-radius: 0 0 var(--圆角) var(--圆角);
    border: none;
}

#user-settings-block input[type="range"] {
    border-radius: var(--圆角) var(--圆角) 0 0 !important;
    height: 4px !important;
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) { 
    border-radius: var(--圆角);
    border: 0.5px solid var(--SmartThemeBorderColor);
    box-shadow:
      1px 1px 7px #1a1a1a,
      0 0 5px #4a4a4a;
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
    -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
    padding-right: 5px;
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
    overflow-y: auto;
}

/* 通知提示框 */
div.toast.toast-success {
    background-color: var(--SmartThemeBlurTintColor) !important;
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
    -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
    border-radius: var(--圆角) !important;
    color: var(--SmartThemeBodyColor) !important;
    box-shadow:
        2px 2px 4px #1a1a1a,
        0 0 4px #4a4a4a !important;
}

/* --- 预设页 --- */
/* 说明文字(如AI可见最大上下文等) */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

/* 滑动条名称 */
.range-block-title {
  text-align: left;
}

/* 角色名称行为 + 继续后缀 */
label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 3px;
}

